// Round 2 — rewritten against a camper who lives in two right-side cells
// (750,350) and (650,650), rarely dashes (and only east/southeast when they do),
// and farms shot windows during our own bursts/slams. Countermeasure: track a
// short ring of recent player positions (not the lifetime heat map, which is
// stale by definition) and slam/burst the centroid led by velocity, with the
// signature punish gated behind a coin flip so it isn't free pressure on the
// scripted panel. Two pressure sources only: slam (led) and a slow spawn drip.
export const meta = {
  name: 'Silo I',
  rationale: 'You only ever stand in two rooms, so I stopped watching the floor and started watching the door between them.',
  version: 2,
};

const PATROL_LEG = 34;
const PATROL_RADIUS = PATROL_LEG * 1.29;
const PATROL_MARGIN = PATROL_RADIUS + 34;
const PATROL_EDGE = 34;

const SPAWN_EVERY = 420; // slow cadence, one pressure source
const RING_SIZE = 60;
const RING_SAMPLE_EVERY = 10;

function __initRaw() {
  return {
    ring: [],       // recent {x,y} samples
    lastSpawn: -999,
    punishRoll: 0.5,
    lastSample: -999,
    anchorX: 400,
    anchorY: 400,
  };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function __decideRaw(view, mem) {
  const boss = view.boss;
  const px = typeof view.player.x === 'number' ? view.player.x : mem.anchorX;
  const py = typeof view.player.y === 'number' ? view.player.y : mem.anchorY;

  // sample the ring
  if (view.tick - mem.lastSample >= RING_SAMPLE_EVERY) {
    mem.lastSample = view.tick;
    if (!Array.isArray(mem.ring)) mem.ring = [];
    mem.ring.push(px);
    mem.ring.push(py);
    while (mem.ring.length > RING_SIZE * 2) {
      mem.ring.shift();
      mem.ring.shift();
    }
  }

  // centroid of the ring, or fall back to live position
  let cx = px, cy = py;
  if (Array.isArray(mem.ring) && mem.ring.length >= 2) {
    let sx = 0, sy = 0, n = 0;
    for (let i = 0; i + 1 < mem.ring.length; i += 2) {
      sx += mem.ring[i];
      sy += mem.ring[i + 1];
      n += 1;
    }
    if (n > 0) {
      cx = sx / n;
      cy = sy / n;
    }
  }
  mem.anchorX = cx;
  mem.anchorY = cy;

  // lead by velocity across a slam's telegraph (40 ticks)
  const vx = typeof view.player.vx === 'number' ? view.player.vx : 0;
  const vy = typeof view.player.vy === 'number' ? view.player.vy : 0;
  let leadX = cx + vx * 40;
  let leadY = cy + vy * 40;
  leadX = clamp(leadX, 0, view.arena.w);
  leadY = clamp(leadY, 0, view.arena.h);

  const dxp = px - boss.x;
  const dyp = py - boss.y;
  const distToPlayer = Math.sqrt(dxp * dxp + dyp * dyp);

  // gate slam distance so it can actually resolve where the player will be
  const dxs = leadX - boss.x;
  const dys = leadY - boss.y;
  const slamDist = Math.sqrt(dxs * dxs + dys * dys);

  // Signature punish: slam the centroid, gated by a roll so it isn't
  // unconditional pressure — answers roughly half of approaches.
  if (boss.cooldowns.slam === 0 && slamDist < 330) {
    if (typeof rand === 'function' ? rand() < 0.5 : mem.punishRoll < 0.5) {
      return { type: 'slam', x: leadX, y: leadY };
    }
  }

  // Slow spawn drip to force movement out of their favorite cells.
  if (boss.cooldowns.spawn === 0 && view.tick - mem.lastSpawn > SPAWN_EVERY) {
    mem.lastSpawn = view.tick;
    return { type: 'spawn', x: cx, y: cy };
  }

  // Contact punish: full ring burst only, cone at contact is a free dodge.
  if (boss.cooldowns.burst === 0 && distToPlayer < 260) {
    const angle = (dxp === 0 && dyp === 0) ? 0 : Math.atan2(dyp, dxp);
    return { type: 'burst', angle: angle, count: 8 };
  }

  // Close the gap from the west, cutting off their east/southeast dash lane.
  const wx = clamp(cx - 220, 0, view.arena.w);
  const wy = cy;
  const tx = wx - boss.x;
  const ty = wy - boss.y;
  const tmag = Math.sqrt(tx * tx + ty * ty);
  if (tmag < 4) {
    return patrol(view, wx, wy);
  }
  return { type: 'move', dx: tx / tmag, dy: ty / tmag };
}

function patrol(view, ax, ay) {
  const boss = view.boss;
  const cx = clamp(ax, PATROL_MARGIN, view.arena.w - PATROL_MARGIN);
  const cy = clamp(ay, PATROL_EDGE, view.arena.h - PATROL_EDGE);
  const phase = view.tick % (PATROL_LEG * 2);
  const leg = phase < PATROL_LEG ? phase : PATROL_LEG * 2 - phase;
  const tx = cx + ((leg / PATROL_LEG) * 2 - 1) * PATROL_RADIUS - boss.x;
  const ty = cy - boss.y;
  const tmag = Math.sqrt(tx * tx + ty * ty);
  if (tmag < 0.001) {
    return { type: 'move', dx: phase < PATROL_LEG ? 1 : -1, dy: 0 };
  }
  return { type: 'move', dx: tx / tmag, dy: ty / tmag };
}

// ---- calibrated by the Judge (deterministic; not written by the Coder) ----
// THROTTLE < 1 forces a rest after every attack so the same read of the player
// lands less often. Measured through Gate 3 and bisected until the round's band.
// Nothing above this line changed except the two renames on init/decide.
const THROTTLE = 0.5;
const THROTTLE_BASE_TICKS = 45;
const THROTTLE_HOLD = THROTTLE >= 1 ? 0 : Math.round((1 / THROTTLE - 1) * THROTTLE_BASE_TICKS);

export function init() {
  const raw = __initRaw();
  const mem = raw !== null && typeof raw === 'object' ? raw : {};
  mem.__judge = { holdUntil: 0 };
  return mem;
}

export function decide(view, mem) {
  const action = __decideRaw(view, mem);
  if (THROTTLE >= 1) return action;
  const type = action === null || typeof action !== 'object' ? '' : action.type;
  if (type !== 'burst' && type !== 'slam' && type !== 'charge' && type !== 'spawn') return action;

  let judge = mem === null || typeof mem !== 'object' ? null : mem.__judge;
  if (judge === null || typeof judge !== 'object') {
    judge = { holdUntil: 0 };
    if (mem !== null && typeof mem === 'object') mem.__judge = judge;
  }
  const tick = typeof view.tick === 'number' && isFinite(view.tick) ? view.tick : 0;
  if (tick >= judge.holdUntil) {
    judge.holdUntil = tick + THROTTLE_HOLD;
    return action;
  }
  // Held. Keep moving, or ACTIVE rejects what the throttle just made fair.
  return __judgeRest(view, tick);
}

/**
 * The resting pattern: a fixed square, straight legs, no read of the player.
 *
 * Straight and not a curve, on purpose. Every reference bot leads its shots off the
 * boss's last-tick velocity, so a curve is unhittable by construction and pushes the
 * panel rate *up* — the throttle would then be subtracting attacks and adding
 * survivability, which is exactly the non-monotonicity it exists to avoid. Measured:
 * an orbiting rest took the round 2 fallback from 0.46 to 0.53 at throttle 0.5; this
 * one takes it down.
 */
function __judgeRest(view, tick) {
  const arena = view.arena;
  const hasArena = arena !== null && typeof arena === 'object';
  const aw = hasArena && isFinite(arena.w) && arena.w > 0 ? arena.w : 800;
  const ah = hasArena && isFinite(arena.h) && arena.h > 0 ? arena.h : 800;
  const bx = isFinite(view.boss.x) ? view.boss.x : aw / 2;
  const by = isFinite(view.boss.y) ? view.boss.y : ah / 2;
  const leg = Math.floor(tick / 34) % 4;
  let dx = leg === 0 ? 1 : leg === 2 ? -1 : 0;
  let dy = leg === 1 ? 1 : leg === 3 ? -1 : 0;
  // A move that clamps against the arena edge displaces nothing, which ACTIVE counts
  // as standing still. Turn round before walking into it.
  if (__judgeBlocked(bx + dx * 40, by + dy * 40, aw, ah)) {
    dx = -dx;
    dy = -dy;
  }
  if (__judgeBlocked(bx + dx * 40, by + dy * 40, aw, ah)) {
    const cx = aw / 2 - bx;
    const cy = ah / 2 - by;
    if (Math.sqrt(cx * cx + cy * cy) > 1) return { type: 'move', dx: cx, dy: cy };
    return { type: 'move', dx: 1, dy: 0 };
  }
  return { type: 'move', dx: dx, dy: dy };
}

function __judgeBlocked(x, y, aw, ah) {
  return x < 34 || x > aw - 34 || y < 34 || y > ah - 34;
}

