candidates.source:
// Round 2 — conservative single-threat rewrite. This player camps two right-side
// cells (750,350) and (650,650), barely dashes (and when they do, it's east/SE),
// and only shoots back during our punish windows. So: one pressure source (burst,
// led onto their predicted position from vx/vy), fired on cooldown, every time.
// No slam (their one dodge came from us slamming a stale cell), no spawn (adds a
// second threat), and never a reward for closing distance — if they walk into us
// we back off and keep shooting range instead of adding a contact punish.
export const meta = {
  name: 'Farsight III',
  rationale: 'You always come back to the same two windows, so I never stop watching them and I never let you close the gap.',
  version: 2,
};

const HOLD_RANGE = 320;   // preferred distance to shoot from
const CLOSE_RANGE = 220;  // if they get this close, we retreat instead of punishing contact
const PATROL_LEG = 34;
const PATROL_RADIUS = PATROL_LEG * 1.29;

export function init() {
  return { phase: 0 };
}

export function decide(view, mem) {
  const boss = view.boss;
  const p = view.player;

  const dx = p.x - boss.x;
  const dy = p.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 1;

  // Lead the burst onto where they're moving, not where they stand.
  const leadT = 12; // ticks of lead, roughly a burst's travel window
  const lx = clamp(p.x + p.vx * leadT, 0, view.arena.w);
  const ly = clamp(p.y + p.vy * leadT, 0, view.arena.h);
  const adx = lx - boss.x;
  const ady = ly - boss.y;
  const angle = (adx === 0 && ady === 0) ? 0 : Math.atan2(ady, adx);

  if (boss.cooldowns.burst === 0) {
    return { type: 'burst', angle: angle, count: 8 };
  }

  // Never punish contact: if they've closed in, back away to keep our range,
  // don't stand and trade.
  if (dist < CLOSE_RANGE) {
    const bx = -dx / dist;
    const by = -dy / dist;
    return { type: 'move', dx: bx, dy: by };
  }

  if (dist > HOLD_RANGE + 40) {
    return { type: 'move', dx: dx / dist, dy: dy / dist };
  }

  // In the sweet spot with burst on cooldown: patrol a short straight leg
  // (never idle) while keeping the range.
  const phase = view.tick % (PATROL_LEG * 2);
  const leg = phase < PATROL_LEG ? phase : PATROL_LEG * 2 - phase;
  const along = ((leg / PATROL_LEG) * 2 - 1);
  // perpendicular to the boss->player line, so we strafe rather than close or flee
  const px = -dy / dist;
  const py = dx / dist;
  const tx = px * along;
  const ty = py * along;
  const tmag = Math.sqrt(tx * tx + ty * ty) || 1;
  return { type: 'move', dx: tx / tmag, dy: ty / tmag };
}

